	last := resp.Trace[len(resp.Trace)-1]
	if last.Msg != "error: http POST "+broken.URL+": status 500" {
		t.Errorf("last trace = %+v, want the action's status error", last)
	}
}

func TestIngestDelegatePostsAgentPayload(t *testing.T) {
